package ai.decisionos.aside;
import android.content.Context;import android.net.Uri;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.zip.*;
/** Plain editable Word document; never labels a draft as submitted. */
final class CampusDocx {
 static String xml(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static byte[] bytes(String title,String body)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(b)){entry(z,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/></Types>");entry(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>");StringBuilder x=new StringBuilder("<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body>");for(String line:(title+"\n\n"+body).split("\n",-1))x.append("<w:p><w:r><w:t xml:space=\"preserve\">").append(xml(line)).append("</w:t></w:r></w:p>");x.append("</w:body></w:document>");entry(z,"word/document.xml",x.toString());}return b.toByteArray();}
 static void entry(ZipOutputStream z,String name,String value)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(value.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
 static Uri write(Context c,String title,String body)throws Exception{byte[] bytes=bytes(title,body);StringBuilder sha=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(bytes))sha.append(String.format(java.util.Locale.ROOT,"%02x",v&255));File dir=new File(c.getFilesDir(),"documents");if(!dir.exists()&&!dir.mkdirs())throw new IOException();String name=sha+".docx";try(FileOutputStream f=new FileOutputStream(new File(dir,name))){f.write(bytes);}return Uri.parse("content://"+c.getPackageName()+".documents/"+name);}
}
